import * as THREE from 'three/webgpu';
import { mix, uv } from 'three/tsl';
import gsap from 'gsap';

const COLORS = {
  backgroundTop: 0x121218,
  backgroundBottom: 0x0b0b10,
  accent: 0xff2a38,
  hairline: 0x23232b,
  paper: 0xe8ecf2,
};

const TYPOGRAPHY = {
  wordmark: { size: 0.34, weight: 600, family: 'Lora', letterSpacing: 0.02 },
  columnHeader: { size: 0.09, weight: 700, family: 'JetBrains Mono', letterSpacing: 0.12 },
  link: { size: 0.13, weight: 400, family: 'JetBrains Mono', letterSpacing: 0 },
  legal: { size: 0.09, weight: 400, family: 'JetBrains Mono', letterSpacing: 0.04 },
};

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const WIDTH = 6.8;
  const HEIGHT = 2.0;

  // Background gradient plane
  const background = createBackground(WIDTH, HEIGHT);
  group.add(background);

  // Top and bottom hairline rules
  createHairlines(group, WIDTH, HEIGHT);

  // Wordmark on left with accent bar
  createWordmarkSection(group, ctx);

  // Three-column link layout on right
  createLinkColumns(group, ctx);

  // Legal notice at bottom
  createLegalNotice(group, ctx);

  // Setup interactive handlers for link hover
  setupEventHandlers(group);

  // Mount animation: fade-up
  const timeline = createMountAnimation(group);

  // Cleanup function
  group.userData.cleanup = () => {
    if (timeline) timeline.kill();

    group.traverse((node) => {
      if (node.geometry) node.geometry.dispose();
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach(m => m.dispose());
        } else {
          node.material.dispose();
        }
      }
    });
  };

  return group;
}

function createBackground(width, height) {
  const geometry = new THREE.PlaneGeometry(width, height);

  // Vertical gradient: bottom #0b0b10 → top #121218
  const uvNode = uv();
  const colorBottom = new THREE.Color(COLORS.backgroundBottom);
  const colorTop = new THREE.Color(COLORS.backgroundTop);
  const gradientColor = mix(colorBottom, colorTop, uvNode.y);

  const material = new THREE.MeshStandardNodeMaterial({
    colorNode: gradientColor,
    roughness: 0.6,
    metalness: 0.2,
    side: THREE.DoubleSide,
  });

  return new THREE.Mesh(geometry, material);
}

function createHairlines(group, width, height) {
  const lineColor = new THREE.Color(COLORS.hairline);

  // Top hairline (full width, top edge)
  const topLineGeo = new THREE.PlaneGeometry(width, 0.006);
  const topLineMat = new THREE.MeshStandardNodeMaterial({
    color: lineColor,
    metalness: 0.2,
    roughness: 0.5,
    side: THREE.DoubleSide,
  });
  const topLine = new THREE.Mesh(topLineGeo, topLineMat);
  topLine.position.set(0, height / 2 - 0.003, 0.001);
  group.add(topLine);

  // Bottom hairline (above legal, full width)
  const bottomLineGeo = new THREE.PlaneGeometry(width, 0.006);
  const bottomLineMat = new THREE.MeshStandardNodeMaterial({
    color: lineColor,
    metalness: 0.2,
    roughness: 0.5,
    side: THREE.DoubleSide,
  });
  const bottomLine = new THREE.Mesh(bottomLineGeo, bottomLineMat);
  bottomLine.position.set(0, -height / 2 + 0.375 + 0.25 - 0.003, 0.001);
  group.add(bottomLine);
}

function createWordmarkSection(group, ctx) {
  // Wordmark: "NOVA ATELIER"
  const wordmark = createTextElement(
    ctx,
    'NOVA ATELIER',
    TYPOGRAPHY.wordmark,
    -2.4,
    0.6
  );
  if (wordmark) group.add(wordmark);

  // Accent bar: 0.3w × 0.02h, emissive red
  const barGeo = new THREE.PlaneGeometry(0.3, 0.02);
  const barMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color(COLORS.accent),
    emissive: new THREE.Color(COLORS.accent),
    emissiveIntensity: 1.4,
    side: THREE.DoubleSide,
  });
  const bar = new THREE.Mesh(barGeo, barMat);
  bar.position.set(-2.4, 0.15, 0.02);
  group.add(bar);
}

function createLinkColumns(group, ctx) {
  const columns = [
    {
      header: 'ATELIER',
      links: ['Features', 'Collection', 'Pricing'],
      x: -0.95,
    },
    {
      header: 'COMPANY',
      links: ['Journal', 'Visit the Atelier', 'Contact'],
      x: 0.625,
    },
    {
      header: 'LEGAL',
      links: ['Privacy', 'Terms', 'Warranty'],
      x: 2.2,
    },
  ];

  columns.forEach((col) => {
    // Column header
    const header = createTextElement(
      ctx,
      col.header,
      TYPOGRAPHY.columnHeader,
      col.x,
      0.65
    );
    if (header) group.add(header);

    // Column links (1.8 line-height ≈ 0.235 units apart)
    col.links.forEach((text, idx) => {
      const link = createTextElement(
        ctx,
        text,
        TYPOGRAPHY.link,
        col.x,
        0.35 - idx * 0.235
      );
      if (link) {
        link.userData.isLink = true;
        link.userData.linkText = text;
        group.add(link);
      }
    });
  });
}

function createLegalNotice(group, ctx) {
  const legal = createTextElement(
    ctx,
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    TYPOGRAPHY.legal,
    0,
    -0.9
  );
  if (legal) group.add(legal);
}

function createTextElement(ctx, text, style, x, y) {
  let textMesh = null;

  try {
    // Use ctx.fontAtlas to create text mesh via MSDF
    textMesh = ctx.fontAtlas.createText(text, {
      size: style.size,
      weight: style.weight,
      family: style.family,
      letterSpacing: style.letterSpacing,
    });

    if (textMesh) {
      textMesh.position.set(x, y, 0.02);
      textMesh.userData.baseColor = new THREE.Color(COLORS.paper);
    }
  } catch (err) {
    console.warn(`Font atlas text creation failed for "${text}":`, err);
  }

  return textMesh;
}

function setupEventHandlers(group) {
  const activeTimelines = new Map();

  group.userData.handlers = {
    onPointerOver: (event) => {
      const obj = event.object;
      if (!obj.userData?.isLink) return;

      if (activeTimelines.has(obj.uuid)) {
        activeTimelines.get(obj.uuid).kill();
      }

      const tl = gsap.timeline();
      tl.to(
        obj,
        {
          color: COLORS.accent,
          duration: 0.14,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        },
        0
      );
      tl.to(
        obj.position,
        {
          z: 0.035,
          duration: 0.14,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        },
        0
      );

      activeTimelines.set(obj.uuid, tl);
    },

    onPointerOut: (event) => {
      const obj = event.object;
      if (!obj.userData?.isLink) return;

      if (activeTimelines.has(obj.uuid)) {
        activeTimelines.get(obj.uuid).kill();
      }

      const tl = gsap.timeline();
      tl.to(
        obj,
        {
          color: COLORS.paper,
          duration: 0.14,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        },
        0
      );
      tl.to(
        obj.position,
        {
          z: 0.02,
          duration: 0.14,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        },
        0
      );

      activeTimelines.set(obj.uuid, tl);
    },
  };
}

function createMountAnimation(group) {
  // Initial state: off-screen, invisible
  group.position.y = 0.2;

  // Collect all materials
  const materials = [];
  group.traverse((node) => {
    if (node.material) {
      if (Array.isArray(node.material)) {
        materials.push(...node.material);
      } else {
        materials.push(node.material);
      }
    }
  });

  // Set initial opacity
  materials.forEach((mat) => {
    mat.transparent = true;
    mat.opacity = 0;
  });

  // Fade-up animation
  const timeline = gsap.timeline();

  // Position: y +0.2 → 0
  timeline.to(
    group.position,
    {
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
    },
    0
  );

  // Opacity: 0 → 1
  materials.forEach((mat) => {
    timeline.to(
      mat,
      {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
      },
      0
    );
  });

  return timeline;
}
